const ALPH = 'abcdefghijklmnopqrstuvwxyz ';
const F1951 = [4.76, 4.03, 3.32, 3.1, null, 2.14]; // Shannon 1951, 27-letter row: F0, F1, F2, F3, (no F4), F_word
const lg = (x) => Math.log2(x);
const h2 = (p) => (p <= 0 || p >= 1 ? 0 : -p * lg(p) - (1 - p) * lg(1 - p));
const MONO = (size, w = 500) => `${w} ${size}px "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace`;

let STATS = null;
/** Plug-in statistics of the corpus: n-gram block entropies, F_N = G-differences, word entropies, context indices. */
function corpusStats() {
  if (STATS) return STATS;
  const T = CORPUS, n = T.length, H = [0];
  const idx = [new Map(), new Map(), new Map()]; // positions following each context of length 1, 2, 3
  for (let k = 1; k <= 4; k++) {
    const c = new Map(); for (let i = 0; i + k <= n; i++) { const g = T.substr(i, k); c.set(g, (c.get(g) || 0) + 1); }
    let h = 0; const tot = n - k + 1; for (const v of c.values()) h -= (v / tot) * lg(v / tot); H.push(h);
  }
  for (let i = 0; i + 1 < n; i++) for (let k = 1; k <= 3 && i - k + 1 >= 0; k++) { const ctx = T.substr(i - k + 1, k), m = idx[k - 1]; let a = m.get(ctx); if (!a) m.set(ctx, (a = [])); a.push(i + 1); }
  const W = T.trim().split(' '), wc = new Map(), bc = new Map(), wpos = new Map();
  W.forEach((w, i) => { wc.set(w, (wc.get(w) || 0) + 1); if (i + 1 < W.length) { const b = w + ' ' + W[i + 1]; bc.set(b, (bc.get(b) || 0) + 1); let a = wpos.get(w); if (!a) wpos.set(w, (a = [])); a.push(i + 1); } });
  const ent = (m, tot) => { let h = 0; for (const v of m.values()) h -= (v / tot) * lg(v / tot); return h; };
  const Hw = ent(wc, W.length), Hb = ent(bc, W.length - 1), L = W.reduce((s, w) => s + w.length, 0) / W.length;
  const F = [lg(27), H[1], H[2] - H[1], H[3] - H[2], H[4] - H[3], Hw / (L + 1), (Hb - Hw) / (L + 1)];
  STATS = { T, n, F, idx, W, wpos, Hw, L, types: wc.size };
  return STATS;
}
/** The n-th order approximation, sampled from the corpus counts (equivalent to Shannon's "open the book at random"). */
function generate(order, len, R) {
  const S = corpusStats(), T = S.T, pick = (a) => a[Math.floor(R() * a.length)];
  if (order === 0) { let s = ''; while (s.length < len) s += ALPH[Math.floor(R() * 27)]; return s; }
  if (order <= 3) {
    let s = T[Math.floor(R() * S.n)];
    while (s.length < len) { const k = Math.min(order - 1, s.length); if (k === 0) { s += T[Math.floor(R() * S.n)]; continue; } const a = S.idx[k - 1].get(s.slice(-k)); s += a ? T[pick(a)] || ' ' : T[Math.floor(R() * S.n)]; }
    return s;
  }
  const W = S.W; let out = [pick(W)];
  while (out.join(' ').length < len) { if (order === 4) out.push(pick(W)); else { const a = S.wpos.get(out[out.length - 1]); out.push(a ? W[pick(a)] : pick(W)); } }
  return out.join(' ');
}
/** Gallager's random-coding exponent for the binary symmetric channel with uniform inputs (bits). */
function Er(R, eps) {
  let best = 0;
  for (let k = 0; k <= 200; k++) { const r = k / 200, a = 1 / (1 + r), E0 = r - (1 + r) * lg(eps ** a + (1 - eps) ** a); best = Math.max(best, E0 - r * R); }
  return best;
}

